import type { Context } from 'hono';
import type { AppEnvironment } from '@/app';
import { writeAudit } from '@/domains/audit/hono-service';
import {
    parseCreateSitePackageRequest,
    parseCreateSitePackageRevisionRequest,
    type SitePackageIdParams,
    type SitePackageRevisionParams
} from '@/domains/site-packages/request';
import type {
    CreateSitePackageResponse,
    CreateSitePackageRevisionResponse,
    DeleteSitePackageRevisionResponse,
    ListSitePackagesResponse,
    PublishSitePackageRevisionResponse,
    RotateSitePackagePreviewTokenResponse,
    SitePackageErrorResponse,
    SitePackageRevisionResponse
} from '@/domains/site-packages/response';
import {
    newSitePackageId,
    mainSiteOrigin,
    storeSitePackageRevision
} from '@/domains/site-packages/site-package-support';
import { sitePackageRepository, services } from '@/middleware/hono-context';
import type { ValidatedRequestContext } from '@/middleware/request-validation';
import { messageFromError, statusFromError } from '@/utils/http/error-response';
import { randomHex } from '@/utils/crypto/random';
import { sha256Hex } from '@/utils/crypto/sha256';
import { deleteObjectWithCompensation } from '@/utils/storage/delete-object';

type StoredRevision = Awaited<ReturnType<typeof storeSitePackageRevision>>;

function revisionDto(revision: {
    id: string;
    package_id: string;
    revision_number: number;
    entry_path: string;
    runtime_mode: 'safe' | 'isolated-script';
    state: 'ready' | 'archived';
    file_count: number;
    total_bytes: number;
    source_sha256: string;
    created_by: number;
    created_at: number;
    published_at: number | null;
}): SitePackageRevisionResponse {
    return {
        id: revision.id,
        packageId: revision.package_id,
        revisionNumber: revision.revision_number,
        entryPath: revision.entry_path,
        runtimeMode: revision.runtime_mode,
        state: revision.state,
        fileCount: revision.file_count,
        totalBytes: revision.total_bytes,
        sourceSha256: revision.source_sha256,
        createdBy: revision.created_by,
        createdAt: revision.created_at,
        publishedAt: revision.published_at
    } satisfies SitePackageRevisionResponse;
}

function packageFailure(error: unknown): { status: 400 | 409 | 413 | 500; message: string } {
    const status = statusFromError(error);
    if (status === 413) return { status: 413, message: messageFromError(error) };
    const message = messageFromError(error);
    if (/unique|constraint|duplicate/i.test(message)) {
        return { status: 409, message: 'slug 或站点包版本已存在' };
    }
    if (status >= 500) return { status: 500, message: '站点包保存失败' };
    return { status: status === 409 ? 409 : 400, message };
}

function createdPackageResponse(
    c: Context<AppEnvironment>,
    packageId: string,
    revisionId: string,
    stored: StoredRevision
): Response {
    return c.json({
        success: true,
        packageId,
        revisionId,
        previewUrl: `${mainSiteOrigin(c)}/site-content/_preview/${stored.previewToken}/`,
        previewToken: stored.previewToken,
        warnings: stored.warnings,
        hasScripts: stored.hasScripts
    } satisfies CreateSitePackageResponse, 201);
}

function createdRevisionResponse(
    c: Context<AppEnvironment>,
    revision: Parameters<typeof revisionDto>[0],
    stored: StoredRevision
): Response {
    return c.json({
        success: true,
        revision: revisionDto(revision),
        previewUrl: `${mainSiteOrigin(c)}/site-content/_preview/${stored.previewToken}/`,
        previewToken: stored.previewToken,
        warnings: stored.warnings,
        hasScripts: stored.hasScripts
    } satisfies CreateSitePackageRevisionResponse, 201);
}

async function confirmStoredRevision(
    c: Context<AppEnvironment>,
    packageId: string,
    revisionId: string,
    stored: StoredRevision
): Promise<{ known: boolean; revision: Parameters<typeof revisionDto>[0] | null }> {
    try {
        const revision = await sitePackageRepository(c).findSitePackageRevisionById(packageId, revisionId);
        if (!revision) return { known: true, revision: null };
        const matches = revision.source_key === stored.revision.sourceKey &&
            revision.source_sha256 === stored.revision.sourceSha256 &&
            revision.manifest_key === stored.revision.manifestKey &&
            revision.preview_token_hash === stored.revision.previewTokenHash;
        return matches
            ? { known: true, revision }
            : { known: false, revision: null };
    } catch (error) {
        console.error('Unable to confirm site-package revision after database error', error);
        return { known: false, revision: null };
    }
}

export async function handleListSitePackages(c: Context<AppEnvironment>): Promise<Response> {
    const packages = await sitePackageRepository(c).listSitePackages();
    const origin = mainSiteOrigin(c);
    return c.json({
        packages: packages.map((sitePackage) => ({
            id: sitePackage.id,
            slug: sitePackage.slug,
            title: sitePackage.title,
            description: sitePackage.description,
            publishedRevisionId: sitePackage.published_revision_id,
            createdBy: sitePackage.created_by,
            updatedBy: sitePackage.updated_by,
            createdAt: sitePackage.created_at,
            updatedAt: sitePackage.updated_at,
            contentOrigin: origin,
            revisions: sitePackage.revisions.map(revisionDto)
        }))
    } satisfies ListSitePackagesResponse);
}

export async function handleCreateSitePackage(c: Context<AppEnvironment>): Promise<Response> {
    const runtime = services(c);
    if (!runtime.storage) throw new Error('Object storage unavailable');
    let packageId = '';
    let revisionId = '';
    let slug = '';
    let stored: StoredRevision | null = null;
    try {
        const request = await parseCreateSitePackageRequest(c);
        slug = request.slug;
        packageId = newSitePackageId();
        revisionId = newSitePackageId();
        const createdAt = Date.now();
        const createdBy = c.get('user')!.id;
        stored = await storeSitePackageRevision(
            runtime.storage,
            packageId,
            revisionId,
            createdBy,
            createdAt,
            request.archive,
            request.manifest,
            (key) => deleteObjectWithCompensation(runtime, key)
        );
        await sitePackageRepository(c).createSitePackageWithRevision({
            id: packageId,
            slug,
            title: request.title,
            description: request.description,
            createdBy,
            createdAt
        }, stored.revision);
        await writeAudit(c, '创建站点包', `${slug}#1`);
        return createdPackageResponse(c, packageId, revisionId, stored);
    } catch (error) {
        if (stored) {
            const confirmation = await confirmStoredRevision(
                c, packageId, revisionId, stored
            );
            if (confirmation.revision) {
                await writeAudit(c, '创建站点包', `${slug}#1`);
                return createdPackageResponse(c, packageId, revisionId, stored);
            }
            if (!confirmation.known) {
                console.error('Site-package create outcome is unknown; preserving stored objects', error);
                return c.json({
                    error: '站点包保存状态待确认'
                } satisfies SitePackageErrorResponse, 500);
            }
            await Promise.allSettled(stored.storedKeys.map((key) =>
                deleteObjectWithCompensation(runtime, key)
            ));
        }
        const failure = packageFailure(error);
        if (failure.status >= 500) console.error('Failed to create site package', error);
        return c.json({ error: failure.message } satisfies SitePackageErrorResponse, failure.status);
    }
}

export async function handleCreateSitePackageRevision(
    c: ValidatedRequestContext<AppEnvironment, 'param', SitePackageIdParams>
): Promise<Response> {
    const runtime = services(c);
    if (!runtime.storage) throw new Error('Object storage unavailable');
    let packageId = '';
    let revisionId = '';
    let packageSlug = '';
    let stored: StoredRevision | null = null;
    try {
        packageId = c.req.valid('param').id;
        const sitePackage = await sitePackageRepository(c).findSitePackageById(packageId);
        if (!sitePackage) {
            return c.json({ error: '站点包不存在' } satisfies SitePackageErrorResponse, 404);
        }
        packageSlug = sitePackage.slug;
        const request = await parseCreateSitePackageRevisionRequest(c);
        revisionId = newSitePackageId();
        const createdAt = Date.now();
        const createdBy = c.get('user')!.id;
        stored = await storeSitePackageRevision(
            runtime.storage,
            packageId,
            revisionId,
            createdBy,
            createdAt,
            request.archive,
            request.manifest,
            (key) => deleteObjectWithCompensation(runtime, key)
        );
        const revision = await sitePackageRepository(c).createSitePackageRevision(stored.revision);
        await writeAudit(c, '上传站点包版本', `${sitePackage.slug}#${revision.revision_number}`);
        return createdRevisionResponse(c, revision, stored);
    } catch (error) {
        if (stored) {
            const confirmation = await confirmStoredRevision(
                c, packageId, revisionId, stored
            );
            if (confirmation.revision) {
                await writeAudit(
                    c,
                    '上传站点包版本',
                    `${packageSlug}#${confirmation.revision.revision_number}`
                );
                return createdRevisionResponse(c, confirmation.revision, stored);
            }
            if (!confirmation.known) {
                console.error(
                    'Site-package revision outcome is unknown; preserving stored objects',
                    error
                );
                return c.json({
                    error: '站点包版本保存状态待确认'
                } satisfies SitePackageErrorResponse, 500);
            }
            await Promise.allSettled(stored.storedKeys.map((key) =>
                deleteObjectWithCompensation(runtime, key)
            ));
        }
        const failure = packageFailure(error);
        if (failure.status >= 500) console.error('Failed to create site package revision', error);
        return c.json({ error: failure.message } satisfies SitePackageErrorResponse, failure.status);
    }
}

export async function handlePublishSitePackageRevision(
    c: ValidatedRequestContext<AppEnvironment, 'param', SitePackageRevisionParams>
): Promise<Response> {
    try {
        const { id: packageId, revisionId } = c.req.valid('param');
        const repository = sitePackageRepository(c);
        const sitePackage = await repository.findSitePackageById(packageId);
        if (!sitePackage) {
            return c.json({ error: '可发布版本不存在' } satisfies SitePackageErrorResponse, 404);
        }
        const publication = await repository.publishSitePackageRevision(
            packageId,
            revisionId,
            c.get('user')!.id,
            Date.now()
        );
        if (!publication) {
            return c.json({ error: '可发布版本不存在' } satisfies SitePackageErrorResponse, 404);
        }
        const { operation, revision: published } = publication;
        if (operation !== 'noop') {
            await writeAudit(
                c,
                operation === 'rollback' ? '回滚站点包版本' : '发布站点包版本',
                `${sitePackage.slug}#${published.revision_number}`
            );
        }
        return c.json({
            success: true,
            packageId,
            revisionId,
            publishedAt: published.published_at,
            operation
        } satisfies PublishSitePackageRevisionResponse);
    } catch (error) {
        const failure = packageFailure(error);
        if (failure.status >= 500) console.error('Failed to publish site package', error);
        return c.json({ error: failure.message } satisfies SitePackageErrorResponse, failure.status);
    }
}

export async function handleDeleteSitePackageRevision(
    c: ValidatedRequestContext<AppEnvironment, 'param', SitePackageRevisionParams>
): Promise<Response> {
    try {
        const { id: packageId, revisionId } = c.req.valid('param');
        const deletion = await sitePackageRepository(c).deleteSitePackageRevision({
            packageId,
            revisionId,
            deletionJobId: newSitePackageId(),
            deletedBy: c.get('user')!.id,
            deletedAt: Date.now()
        });
        if (!deletion) {
            return c.json({ error: '站点包历史版本不存在' } satisfies SitePackageErrorResponse, 404);
        }
        if (deletion.kind === 'published') {
            return c.json({
                error: '当前线上版本不能删除，请先发布其他版本'
            } satisfies SitePackageErrorResponse, 409);
        }
        await writeAudit(
            c,
            deletion.packageDeleted ? '删除站点包' : '删除站点包历史版本',
            deletion.packageDeleted
                ? deletion.sitePackage.slug
                : `${deletion.sitePackage.slug}#${deletion.revision.revision_number}`
        );
        return c.json({
            success: true,
            packageId,
            revisionId,
            revisionNumber: deletion.revision.revision_number,
            packageDeleted: deletion.packageDeleted,
            objectCleanup: 'queued'
        } satisfies DeleteSitePackageRevisionResponse);
    } catch (error) {
        const failure = packageFailure(error);
        if (failure.status >= 500) console.error('Failed to delete site package revision', error);
        return c.json({ error: failure.message } satisfies SitePackageErrorResponse, failure.status);
    }
}

export async function handleRotateSitePackagePreviewToken(
    c: ValidatedRequestContext<AppEnvironment, 'param', SitePackageRevisionParams>
): Promise<Response> {
    try {
        const { id: packageId, revisionId } = c.req.valid('param');
        const previewToken = randomHex(32);
        const previewTokenHash = await sha256Hex(new TextEncoder().encode(previewToken));
        const rotated = await sitePackageRepository(c).rotateSitePackagePreviewToken(
            packageId,
            revisionId,
            previewTokenHash
        );
        if (!rotated) {
            return c.json({ error: '站点包版本不存在' } satisfies SitePackageErrorResponse, 404);
        }
        await writeAudit(c, '刷新站点包预览令牌', `${packageId}:${revisionId}`);
        return c.json({
            success: true,
            packageId,
            revisionId,
            previewToken,
            previewUrl: `${mainSiteOrigin(c)}/site-content/_preview/${previewToken}/`
        } satisfies RotateSitePackagePreviewTokenResponse);
    } catch (error) {
        const failure = packageFailure(error);
        if (failure.status >= 500) console.error('Failed to rotate preview token', error);
        return c.json({ error: failure.message } satisfies SitePackageErrorResponse, failure.status);
    }
}
